using System.Collections;
using System.Collections.Generic;
using UnityEngine;

// Sound effects and music, generated by Visuals/audio_generator (sfx.py, music.py) into
// Resources/Audio/Sfx and Resources/Audio/Music.
//   Audio.Play("SwordHit")            one-shot effect (pooled sources, random pitch wobble)
//   Audio.Music("Boss")               crossfade to a looping track (null = fade out)
//   Audio.Sting("FloorClear")         short music cue; the music ducks under it
// Volumes come from Settings. Runs on unscaled time, so fades keep going while paused.
public static class Audio
{
    const int PoolSize = 20;
    const int MaxSameSound = 3;          // copies of one effect that may overlap
    const float MinRepeatGap = 0.035f;   // seconds before the same effect may start again

    static AudioRunner runner;
    static AudioSource[] pool;
    static AudioSource[] music;
    static AudioSource sting;
    static int activeMusic;
    static string currentMusic;
    static float duck = 1f;
    static readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
    static readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void ResetStatics()
    {
        runner = null;
        pool = null;
        music = null;
        sting = null;
        currentMusic = null;
        duck = 1f;
        clips.Clear();
        lastPlayed.Clear();
    }

    static void Ensure()
    {
        if (runner != null) return;
        var go = new GameObject("Audio");
        Object.DontDestroyOnLoad(go);
        runner = go.AddComponent<AudioRunner>();
        pool = new AudioSource[PoolSize];
        for (int i = 0; i < PoolSize; i++)
        {
            pool[i] = go.AddComponent<AudioSource>();
            pool[i].playOnAwake = false;
        }
        music = new AudioSource[2];
        for (int i = 0; i < 2; i++)
        {
            music[i] = go.AddComponent<AudioSource>();
            music[i].playOnAwake = false;
            music[i].loop = true;
            music[i].volume = 0f;
            music[i].ignoreListenerPause = true;
        }
        sting = go.AddComponent<AudioSource>();
        sting.playOnAwake = false;
        sting.ignoreListenerPause = true;
    }

    static AudioClip Clip(string path)
    {
        if (!clips.TryGetValue(path, out var clip))
        {
            clip = Resources.Load<AudioClip>("Audio/" + path);
            if (clip == null) Debug.LogWarning($"Audio: missing clip Resources/Audio/{path}");
            clips[path] = clip;
        }
        return clip;
    }

    // One-shot sound effect. pitch: base pitch (champions play their sounds lower); jitter: random +-.
    public static void Play(string name, float volume = 1f, float pitch = 1f, float jitter = 0.06f)
    {
        Ensure();
        var clip = Clip("Sfx/" + name);
        if (clip == null) return;

        float now = Time.unscaledTime;
        if (lastPlayed.TryGetValue(name, out float last) && now - last < MinRepeatGap) return;
        int playing = 0;
        AudioSource free = null, oldest = null;
        foreach (var s in pool)
        {
            if (s.isPlaying)
            {
                if (s.clip == clip) playing++;
                if (oldest == null || s.time > oldest.time) oldest = s;
            }
            else if (free == null) free = s;
        }
        if (playing >= MaxSameSound) return;
        var source = free ?? oldest;
        lastPlayed[name] = now;

        source.clip = clip;
        source.volume = Mathf.Clamp01(volume * Settings.SfxVolume);
        source.pitch = pitch * (1f + Random.Range(-jitter, jitter));
        source.Play();
    }

    // Crossfades to a looping track (Resources/Audio/Music/<name>). Same track = no change.
    public static void Music(string name, float fade = 0.8f)
    {
        Ensure();
        if (name == currentMusic) return;
        currentMusic = name;
        var from = music[activeMusic];
        activeMusic = 1 - activeMusic;
        var to = music[activeMusic];
        var clip = name != null ? Clip("Music/" + name) : null;
        runner.StopAllCoroutines();
        duck = 1f;
        runner.StartCoroutine(Crossfade(from, to, clip, fade));
    }

    // A short music cue (floor clear, game over); the looping music ducks underneath it.
    public static void Sting(string name, bool stopMusic = false)
    {
        Ensure();
        var clip = Clip("Music/" + name);
        if (clip == null) return;
        sting.clip = clip;
        sting.volume = Settings.MusicVolume;
        sting.Play();
        if (stopMusic) Music(null, 0.3f);
        else runner.StartCoroutine(Duck(clip.length));
    }

    public static void RefreshVolume()
    {
        if (music == null) return;
        music[activeMusic].volume = Settings.MusicVolume * duck;
        sting.volume = Settings.MusicVolume;
    }

    static IEnumerator Crossfade(AudioSource from, AudioSource to, AudioClip clip, float fade)
    {
        if (clip != null)
        {
            to.clip = clip;
            to.volume = 0f;
            to.Play();
        }
        float startFrom = from.volume;
        for (float t = 0f; t < fade; t += Time.unscaledDeltaTime)
        {
            float k = t / fade;
            from.volume = startFrom * (1f - k);
            if (clip != null) to.volume = Settings.MusicVolume * duck * k;
            yield return null;
        }
        from.volume = 0f;
        from.Stop();
        if (clip != null) to.volume = Settings.MusicVolume * duck;
    }

    static IEnumerator Duck(float length)
    {
        duck = 0.25f;
        RefreshVolume();
        yield return new WaitForSecondsRealtime(length);
        for (float t = 0f; t < 0.6f; t += Time.unscaledDeltaTime)
        {
            duck = Mathf.Lerp(0.25f, 1f, t / 0.6f);
            RefreshVolume();
            yield return null;
        }
        duck = 1f;
        RefreshVolume();
    }
}

// Hosts Audio's fade coroutines (added at runtime)
public class AudioRunner : MonoBehaviour { }
